+const CONSTRAINT_FORMATTERS: Record<string, (params: Record<string, unknown>) => string> = {
+  required: () => 'missing required property',
+  type: params => `must be ${String(params.type)}`,
+  enum: () => 'must be one of the allowed enum values',
