+function compileSyncSchema(compiler: AjvInstance, toolName: string, inputSchema: Record<string, unknown>) {
+  if (!isSyncJsonSchema(inputSchema)) {
+    throw new Error(`Invalid inputSchema for tool "${toolName}": unsupported async or metadata fields`);
+  }
