+
+function isSyncJsonSchema(schema: Record<string, unknown>): schema is SyncJsonSchema {
   const metaStringsValid = [schema.id, schema.$id, schema.$schema].every(
     field => field === undefined || typeof field === 'string'
   );
   return metaStringsValid && schema.$async !== true;
