+
+function formatValidationFailures(errors: SchemaValidator['errors']): string[] {
+  return (errors ?? []).map(describeValidationFailure);
+}
+
+function describeValidationFailure(failure: ValidationErrorItem): string {
+  const {keyword, instancePath, params} = failure;
+  const basePath = formatInstancePath(instancePath);
+  const fieldPath = keyword === 'required' ? joinFieldPath(basePath, String(params.missingProperty)) : basePath;
+  const targetPath = fieldPath || '<root>';
+  const formatter = CONSTRAINT_FORMATTERS[keyword];
+  const constraint = formatter ? formatter(params) : `failed ${keyword} constraint`;
+  return `${targetPath}: ${constraint}`;
+}
+
+function formatInstancePath(instancePath: string): string {
+  if (!instancePath) return '';
+  const trimmed = instancePath.slice(1);
+  const rawSegments = trimmed.split('/');
+  const decodedSegments = rawSegments.map(decodeJsonPointerSegment);
+  return decodedSegments.join('.');
+}
+
+function decodeJsonPointerSegment(segment: string): string {
+  const withSlashes = segment.replace(/~1/g, '/');
+  return withSlashes.replace(/~0/g, '~');
+}
+
+function joinFieldPath(basePath: string, propertyName: string): string {
+  return basePath ? `${basePath}.${propertyName}` : propertyName;
+}

